package com.opensocket.aievent.core.iam.authentication.domain;
import com.opensocket.aievent.core.iam.security.contract.SecurityEpoch;import com.opensocket.aievent.core.iam.security.contract.TenantRef;import java.time.Instant;import java.util.Objects;import java.util.Optional;import java.util.Set;
public final class BrowserSession{private final String sessionId;private final CredentialSubjectType subjectType;private final String subjectId;private final TenantRef tenant;private final Set<String> methods;private final Optional<Instant> mfaVerifiedAt;private final Instant createdAt;private final Instant lastSeenAt;private final Instant idleExpiresAt;private final Instant absoluteExpiresAt;private final String ipAddress;private final String userAgent;private final Status status;private final Optional<Instant> revokedAt;private final String revokedBy;private final String revokeReason;private final SecurityEpoch securityEpoch;private final long version;private BrowserSession(String sessionId,CredentialSubjectType subjectType,String subjectId,TenantRef tenant,Set<String> methods,Optional<Instant> mfaVerifiedAt,Instant createdAt,Instant lastSeenAt,Instant idleExpiresAt,Instant absoluteExpiresAt,String ipAddress,String userAgent,Status status,Optional<Instant> revokedAt,String revokedBy,String revokeReason,SecurityEpoch epoch,long version){this.sessionId=Text.required(sessionId,"sessionId",256);this.subjectType=Objects.requireNonNull(subjectType,"subjectType");this.subjectId=Text.required(subjectId,"subjectId",128);this.tenant=Objects.requireNonNull(tenant,"tenant");this.methods=methods==null?Set.of():Set.copyOf(methods);this.mfaVerifiedAt=mfaVerifiedAt==null?Optional.empty():mfaVerifiedAt;this.createdAt=Objects.requireNonNull(createdAt,"createdAt");this.lastSeenAt=Objects.requireNonNull(lastSeenAt,"lastSeenAt");this.idleExpiresAt=Objects.requireNonNull(idleExpiresAt,"idleExpiresAt");this.absoluteExpiresAt=Objects.requireNonNull(absoluteExpiresAt,"absoluteExpiresAt");if(!absoluteExpiresAt.isAfter(createdAt)||idleExpiresAt.isAfter(absoluteExpiresAt))throw new IllegalArgumentException("session expiration is invalid");this.ipAddress=Text.optional(ipAddress,128);this.userAgent=Text.optional(userAgent,1000);this.status=Objects.requireNonNull(status,"status");this.revokedAt=revokedAt==null?Optional.empty():revokedAt;this.revokedBy=Text.optional(revokedBy,128);this.revokeReason=Text.optional(revokeReason,500);this.securityEpoch=epoch==null?SecurityEpoch.ZERO:epoch;if(version<1)throw new IllegalArgumentException("version must be positive");this.version=version;}
public static BrowserSession create(String id,CredentialSubjectType type,String subject,TenantRef tenant,Set<String> methods,Optional<Instant> mfa,Instant at,SessionPolicy policy,String ip,String agent,SecurityEpoch epoch){return new BrowserSession(id,type,subject,tenant,methods,mfa,at,at,min(at.plus(policy.idleTimeout()),at.plus(policy.absoluteTimeout())),at.plus(policy.absoluteTimeout()),ip,agent,Status.ACTIVE,Optional.empty(),"","",epoch,1);}public static BrowserSession reconstitute(String id,CredentialSubjectType type,String subject,TenantRef tenant,Set<String> methods,Optional<Instant> mfa,Instant created,Instant lastSeen,Instant idle,Instant absolute,String ip,String agent,Status status,Optional<Instant> revoked,String revokedBy,String reason,SecurityEpoch epoch,long version){return new BrowserSession(id,type,subject,tenant,methods,mfa,created,lastSeen,idle,absolute,ip,agent,status,revoked,revokedBy,reason,epoch,version);}public BrowserSession touch(Instant at,SessionPolicy policy){requireActive(at);return new BrowserSession(sessionId,subjectType,subjectId,tenant,methods,mfaVerifiedAt,createdAt,at,min(at.plus(policy.idleTimeout()),absoluteExpiresAt),absoluteExpiresAt,ipAddress,userAgent,status,revokedAt,revokedBy,revokeReason,securityEpoch,version+1);}public BrowserSession revoke(String actor,String reason,Instant at){if(status==Status.REVOKED)return this;return new BrowserSession(sessionId,subjectType,subjectId,tenant,methods,mfaVerifiedAt,createdAt,lastSeenAt,idleExpiresAt,absoluteExpiresAt,ipAddress,userAgent,Status.REVOKED,Optional.of(at),actor,Text.required(reason,"reason",500),securityEpoch,version+1);}public void requireActive(Instant at){if(status==Status.REVOKED)throw new AuthenticationDomainException(AuthenticationReasonCode.AUTH_SESSION_REVOKED,"Session is revoked");if(!at.isBefore(idleExpiresAt)||!at.isBefore(absoluteExpiresAt))throw new AuthenticationDomainException(AuthenticationReasonCode.AUTH_SESSION_EXPIRED,"Session is expired");}private static Instant min(Instant a,Instant b){return a.isBefore(b)?a:b;}public enum Status{ACTIVE,REVOKED}public String sessionId(){return sessionId;}public CredentialSubjectType subjectType(){return subjectType;}public String subjectId(){return subjectId;}public TenantRef tenant(){return tenant;}public Set<String> methods(){return methods;}public Optional<Instant> mfaVerifiedAt(){return mfaVerifiedAt;}public Instant createdAt(){return createdAt;}public Instant lastSeenAt(){return lastSeenAt;}public Instant idleExpiresAt(){return idleExpiresAt;}public Instant absoluteExpiresAt(){return absoluteExpiresAt;}public String ipAddress(){return ipAddress;}public String userAgent(){return userAgent;}public Status status(){return status;}public Optional<Instant> revokedAt(){return revokedAt;}public String revokedBy(){return revokedBy;}public String revokeReason(){return revokeReason;}public SecurityEpoch securityEpoch(){return securityEpoch;}public long version(){return version;}}
